svg.script:
    (() => {
      const CELL_SIZE = 128;

      for (const icon of document.querySelectorAll("svg[data-cell]")) {
        const cell = icon.getAttribute("data-cell");
        const match = /^\s*(\d+)\s*,\s*(\d+)\s*$/.exec(cell);

        if (!match) 
          {
          throw new Error( `Invalid data-cell on ${icon.id}: "${cell}"` );
          }

        const gridX = Number(match[1]);
        const gridY = Number(match[2]);

        icon.setAttribute("x", String(gridX * CELL_SIZE));
        icon.setAttribute("y", String(gridY * CELL_SIZE));
      }
    })();
